INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g7-20260922-library-club','The Library Club','图书馆阅读小组','monologue','Listen to the passage and choose the best answer for each question.','Hello, everyone. Our library club meets on Tuesday after school. We meet in Room Twelve, not in the library, because the library is being cleaned this week. Please arrive at four ten. You do not need to bring a book. Miss Green will give each group a short story. Bring a pencil to write down new words. The meeting ends at five, so you can take the school bus home.','大家好。我们的图书馆阅读小组在周二放学后活动。本周图书馆正在打扫，所以我们在十二号教室集合，而不是图书馆。请在四点十分到达。你不需要带书，格林老师会给每组一个短篇故事。请带一支铅笔记录生词。活动五点结束，因此你可以乘校车回家。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g7-20260922-library-club-67ef88f1ec46.mp3',27,1000,1,1790047718676,NULL,13) ON CONFLICT (material_id) DO NOTHING;
