INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g7-20260922-lost-bag','A Bag at the Sports Center','体育中心的失物招领','monologue','Listen to the passage and choose the best answer for each question.','Good afternoon. We have found a blue schoolbag near the swimming pool. There is a yellow water bottle and a pair of black shoes inside. There are no books in the bag. If it is yours, please come to the front desk before six this evening. Ask for Mr Brown. You will need to tell him the name written inside the bag. Please do not go to the swimming teacher to collect it.','下午好。我们在游泳池附近发现了一个蓝色书包，里面有一个黄色水瓶和一双黑鞋，没有书。如果是你的，请在今晚六点前到前台找布朗先生。你需要告诉他书包里面写的名字。请不要找游泳老师领取。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g7-20260922-lost-bag-d3bd30fde139.mp3',27,1001,1,1790047718676,NULL,13) ON CONFLICT (material_id) DO NOTHING;
