INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g7-20260922-picnic-plan','Our Sunday Picnic','周日野餐安排','monologue','Listen to the passage and choose the best answer for each question.','Hi, Lucy. This is Emma. Our picnic is on Sunday, not Saturday. My brother has a football game on Saturday, and we want him to come too. Let''s meet at the park gate at ten in the morning. I will bring sandwiches, and my brother will bring some apples. Could you bring drinking water? We can sit under the big tree beside the lake. Call me this evening if you cannot come.','嗨，露西，我是艾玛。我们的野餐在周日，不是周六。我哥哥周六有一场足球比赛，我们也想让他参加。我们上午十点在公园门口见吧。我会带三明治，哥哥会带苹果。你能带饮用水吗？我们可以坐在湖边的大树下。如果你不能来，请今晚给我打电话。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g7-20260922-picnic-plan-230a08e6a2f4.mp3',27,1002,1,1790047718676,NULL,13) ON CONFLICT (material_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g7-20260922-picnic-plan-q1','original-g7-20260922-picnic-plan','detail','When is the picnic?','C','留言明确更正：野餐在 Sunday，Saturday 是哥哥比赛的日子。',0,2) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g7-20260922-picnic-plan-q1','A','On Friday.',0) ON CONFLICT (question_id,option_id) DO NOTHING;
