INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g7-20260922-picnic-plan-q2','D','Drinking water.',3) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g7-20260922-picnic-plan-q3','original-g7-20260922-picnic-plan','inference','Why is the picnic planned for Sunday?','A','哥哥周六比赛，大家希望他也来，因此把野餐安排在周日。',2,2) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g7-20260922-picnic-plan-q3','A','So Emma''s brother can join them.',0) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g7-20260922-picnic-plan-q3','B','Because the park is closed on Saturday.',1) ON CONFLICT (question_id,option_id) DO NOTHING;
