INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g7-20260922-fruit-shop','Shopping for Fruit','帮家人买水果','monologue','Listen to the passage and choose the best answer for each question.','I went to the fruit shop with ten yuan this morning. Mum wanted four oranges, but there were only two left. I bought the two oranges for four yuan and a small bag of apples for five yuan. The shopkeeper gave me one yuan back. I carried the fruit home in my schoolbag because I did not want another plastic bag. Mum was happy with the apples. She used them to make a fruit salad for lunch.','今天早上我带着十元去了水果店。妈妈想要四个橙子，但店里只剩两个。我花四元买了两个橙子，又花五元买了一小袋苹果。店主找回一元。我不想再用一个塑料袋，就用书包把水果带回家。妈妈很喜欢这些苹果，用它们做了午餐的水果沙拉。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g7-20260922-fruit-shop-a0f14ed7efd4.mp3',28,1003,1,1790047718676,NULL,13) ON CONFLICT (material_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g7-20260922-fruit-shop-q1','original-g7-20260922-fruit-shop','detail','How many oranges did the speaker buy?','B','妈妈想要四个，但店里只剩两个，实际购买的是 two oranges。',0,2) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g7-20260922-fruit-shop-q1','A','One.',0) ON CONFLICT (question_id,option_id) DO NOTHING;
