INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g7-20260922-fruit-shop-q1','C','Four.',2) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g7-20260922-fruit-shop-q1','D','Five.',3) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g7-20260922-fruit-shop-q2','original-g7-20260922-fruit-shop','detail','How much did the speaker spend in total?','C','橙子四元，苹果五元，共九元；十元是出门时带的钱。',1,2) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g7-20260922-fruit-shop-q2','A','Four yuan.',0) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g7-20260922-fruit-shop-q2','B','Five yuan.',1) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g7-20260922-fruit-shop-q2','C','Nine yuan.',2) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g7-20260922-fruit-shop-q2','D','Ten yuan.',3) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g7-20260922-fruit-shop-q3','original-g7-20260922-fruit-shop','detail','Why did the speaker use a schoolbag?','D','原文直接说明 because I did not want another plastic bag。',2,2) ON CONFLICT (question_id) DO NOTHING;
