INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g8-20260922-museum-trip','A Change to the Museum Trip','博物馆出行变更','monologue','Listen to the passage and choose the best answer for each question.','Here is an update about our museum trip tomorrow. The train service has been cancelled, so we will travel by coach instead. Meet outside school at eight fifteen, fifteen minutes earlier than planned. You do not need to pay extra for the coach. The museum ticket is already included in your trip fee. However, the cafe will be closed, so bring a packed lunch. We will return to school at four thirty, as originally planned.','下面通知明天博物馆之行的变更。火车班次已取消，因此我们改乘长途客车。请八点十五分在校外集合，比原计划提前十五分钟。乘客车不需要额外付费，博物馆门票也已包含在活动费中。不过咖啡馆将关闭，请自带午餐。我们仍按原计划在四点半返回学校。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g8-20260922-museum-trip-e90304195af6.mp3',29,1004,1,1790047718676,NULL,15) ON CONFLICT (material_id) DO NOTHING;
