INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g8-20260922-healthy-routine','A Small Change to My Morning','早晨习惯的小改变','monologue','Listen to the passage and choose the best answer for each question.','Last month, I often felt sleepy in my first lesson. I thought I needed a bigger breakfast, but my teacher suggested looking at my evening routine. I usually played games on my phone until midnight. Now I leave my phone in the living room at nine and read for twenty minutes before bed. I still eat the same breakfast. After two weeks, I can listen more carefully in class. Changing my bedtime has helped more than changing my food.','上个月，我常在第一节课犯困。我以为需要多吃早餐，但老师建议看看晚间习惯。我以前经常用手机玩游戏到午夜。现在我九点把手机放在客厅，睡前阅读二十分钟。早餐仍和以前一样。两周后，我上课能更认真地听讲了。改变就寝习惯比改变饮食更有帮助。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g8-20260922-healthy-routine-5bb545e8da42.mp3',30,1005,1,1790047718676,NULL,15) ON CONFLICT (material_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g8-20260922-healthy-routine-q1','original-g8-20260922-healthy-routine','detail','What problem did the speaker have?','D','开头说明 often felt sleepy in my first lesson，问题是第一节课犯困。',0,2) ON CONFLICT (question_id) DO NOTHING;
