INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g8-20260922-garden-project','Our School Garden','校园菜园的小实验','monologue','Listen to the passage and choose the best answer for each question.','Our class planted vegetables behind the science building in April. At first, we watered them every afternoon, but some leaves turned yellow. We asked a local gardener for advice. She explained that the soil was already wet and that too much water could harm the plants. Now we check the soil before watering. We also keep a notebook of changes each week. In June, we picked our first tomatoes and used the notebook to explain what we had learned.','四月，我们班在科学楼后种了蔬菜。起初每天午后浇水，但有些叶子发黄。我们向当地园艺师请教。她解释说土已经很湿，浇水过多会伤害植物。现在我们先检查土壤再浇水，还每周用笔记本记录变化。六月，我们摘下第一批西红柿，并用记录解释学到的知识。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g8-20260922-garden-project-38f7b0a02724.mp3',31,1006,1,1790047718676,NULL,15) ON CONFLICT (material_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g8-20260922-garden-project-q1','original-g8-20260922-garden-project','detail','What caused problems for some plants?','C','园艺师指出土壤已经很湿，too much water 会伤害植物。',0,2) ON CONFLICT (question_id) DO NOTHING;
