INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g8-20260922-book-exchange','Saturday''s Book Exchange','周六图书交换活动','monologue','Listen to the passage and choose the best answer for each question.','The community center is holding a book exchange this Saturday. Bring up to three books that are clean and complete. For each book you bring, you receive one ticket, which you can exchange for another book. School workbooks are not accepted because many already have answers written in them. The exchange opens at ten, but volunteers should arrive at nine thirty to arrange the tables. Any books left at the end will be sent to a village library.','社区中心本周六举办图书交换活动。每人最多可带三本干净、完整的书，每带一本就能得到一张票，用来换另一本书。活动不接收学校练习册，因为许多已经写有答案。交换十点开始，志愿者需九点半到达布置桌子。活动结束后剩余的书将送往乡村图书馆。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g8-20260922-book-exchange-ea8391b0f923.mp3',31,1007,1,1790047718676,NULL,15) ON CONFLICT (material_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g8-20260922-book-exchange-q1','original-g8-20260922-book-exchange','detail','How many tickets does someone get for bringing two accepted books?','B','每本符合要求的书换一张票，因此两本可以获得两张票。',0,2) ON CONFLICT (question_id) DO NOTHING;
