INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g9-20260922-repair-cafe','Learning at a Repair Cafe','维修工坊里的收获','monologue','Listen to the passage and choose the best answer for each question.','When my desk lamp stopped working, I planned to buy a new one. My neighbour suggested taking it to a repair cafe, where volunteers help people fix everyday objects. A volunteer found a loose wire and repaired it in ten minutes. There was no charge, although visitors could leave a donation. More importantly, she showed me how to check the lamp safely next time. I left with a working lamp and a useful skill. I now think twice before throwing things away.','台灯坏掉时，我原本打算买新的。邻居建议去维修工坊，那里的志愿者帮助人们修理日常物品。一位志愿者发现电线松了，十分钟就修好了。维修不收费，不过来访者可以捐款。更重要的是，她教我下次如何安全检查台灯。我带着修好的灯和实用技能离开，现在扔东西前会多想一想。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g9-20260922-repair-cafe-c86923aab1ee.mp3',30,1008,1,1790047718676,NULL,17) ON CONFLICT (material_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g9-20260922-repair-cafe-q1','original-g9-20260922-repair-cafe','detail','What was wrong with the lamp?','A','志愿者发现的是 a loose wire，即电线松动。',0,2) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-repair-cafe-q1','A','A wire was loose.',0) ON CONFLICT (question_id,option_id) DO NOTHING;
