INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g9-20260922-repair-cafe-q2','original-g9-20260922-repair-cafe','detail','What does the speaker say about the cost?','B','原文说 no charge，但 visitors could leave a donation，捐款是自愿的。',1,2) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-repair-cafe-q2','A','Everyone had to pay ten yuan.',0) ON CONFLICT (question_id,option_id) DO NOTHING;
