INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g9-20260922-repair-cafe-q3','original-g9-20260922-repair-cafe','inference','How has the experience changed the speaker?','C','结尾 think twice before throwing things away 表明会先考虑维修和继续使用。',2,2) ON CONFLICT (question_id) DO NOTHING;
