INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g9-20260922-travel-choice','Choosing a Journey','怎样选择出行方式','monologue','Listen to the passage and choose the best answer for each question.','For our weekend visit to another city, my family compared flying with taking the train. The flight itself was only an hour, while the train journey took three hours. However, the airport was far from our home, and we would need to arrive two hours before departure. The railway station was a short bus ride away. When we counted the whole journey, the train was more convenient. It also cost less. We chose the train, even though the flight looked faster at first.','周末去另一座城市前，我们比较了飞机和火车。飞行本身只需一小时，而火车要三小时。但机场离家很远，还需要提前两小时到达。火车站坐一小段公交车就到。算上完整行程后，火车更方便，也更便宜。所以虽然飞机起初看起来更快，我们还是选了火车。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g9-20260922-travel-choice-e13d87f41a5a.mp3',30,1009,1,1790047718676,NULL,17) ON CONFLICT (material_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g9-20260922-travel-choice-q1','original-g9-20260922-travel-choice','detail','How long was the flight itself?','D','the flight itself was only an hour；两小时是提前到机场的时间。',0,2) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-travel-choice-q1','A','Two hours.',0) ON CONFLICT (question_id,option_id) DO NOTHING;
