INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g9-20260922-online-survey','Checking a Survey Result','问卷结果可靠吗','monologue','Listen to the passage and choose the best answer for each question.','Our school newspaper wanted to find out whether students preferred online or printed books. At first, we posted a survey only in the school reading club''s online group. Most replies supported online books. Our teacher pointed out that this group did not represent every student. We then asked students from each year group during lunch, including those who rarely used the internet. The results became more balanced. We learned that who answers a survey can be as important as the questions themselves.','校报想调查学生更喜欢电子书还是纸质书。起初，我们只在阅读社团的线上群发布问卷，大多数回答支持电子书。老师指出，这个群体不能代表全体学生。之后我们在午餐时询问各年级学生，也包括很少上网的人。结果变得更均衡。我们认识到，谁来回答问卷与问题本身同样重要。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g9-20260922-online-survey-dbb8828f82d4.mp3',33,1010,1,1790047718676,NULL,17) ON CONFLICT (material_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g9-20260922-online-survey-q1','original-g9-20260922-online-survey','detail','Where was the first survey shared?','C','第一次只在 school reading club''s online group 发布。',0,2) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-online-survey-q1','A','In every classroom.',0) ON CONFLICT (question_id,option_id) DO NOTHING;
