INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-online-survey-q1','C','In the reading club''s online group.',2) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-online-survey-q1','D','On a city television programme.',3) ON CONFLICT (question_id,option_id) DO NOTHING;
