INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g9-20260922-online-survey-q3','original-g9-20260922-online-survey','main_idea','What did the students learn?','A','扩大到不同年级及较少上网的人后结果变化，说明回答者的选择会影响调查。',2,2) ON CONFLICT (question_id) DO NOTHING;
