INSERT INTO public.listening_materials (material_id,title,title_zh,material_type,prompt_text,transcript,transcript_zh,audio_url,estimated_seconds,sort_order,version,updated_at,book_id,grade_level) VALUES ('original-g9-20260922-food-waste','Less Waste at Lunch','减少午餐浪费','monologue','Listen to the passage and choose the best answer for each question.','Our school tried to reduce food waste by putting up posters, but the amount of waste hardly changed. Then the student council spoke to diners. Many said the standard portions were too large, especially on days when they were not very hungry. The kitchen began offering a smaller portion at a lower price, with extra food available if needed. After a month, waste had fallen. The council concluded that making a practical change was more effective than simply reminding people to waste less.','学校先张贴海报来减少食物浪费，但浪费量几乎没变。随后学生会和用餐者交流，很多人认为标准份量太大，尤其在不太饿的时候。厨房开始提供价格更低的小份餐，不够还可以加。一个月后，浪费减少了。学生会认为，实际改变比单纯提醒少浪费更有效。','https://xojbnrxnkgkqacrkcmqc.supabase.co/storage/v1/object/public/audio-pep/original/20260922/original-g9-20260922-food-waste-d9fb901c4f98.mp3',32,1011,1,1790047718676,NULL,17) ON CONFLICT (material_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g9-20260922-food-waste-q1','original-g9-20260922-food-waste','detail','What happened after the posters were put up?','B','原文说 the amount of waste hardly changed，海报效果不明显。',0,2) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-food-waste-q1','A','Waste disappeared completely.',0) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-food-waste-q1','B','The amount of waste hardly changed.',1) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-food-waste-q1','C','Meals became more expensive.',2) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-food-waste-q1','D','Students stopped eating lunch.',3) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g9-20260922-food-waste-q2','original-g9-20260922-food-waste','detail','What change did the kitchen make?','C','厨房提供小份餐，并允许按需加餐，没有禁止加餐。',1,2) ON CONFLICT (question_id) DO NOTHING;
