INSERT INTO public.listening_questions (question_id,material_id,question_type,stem,correct_option_id,explanation,sort_order,reward_token) VALUES ('original-g9-20260922-food-waste-q3','original-g9-20260922-food-waste','inference','Why was the second approach more effective?','D','访谈发现份量过大是剩饭原因，小份加按需补充直接解决了这一问题。',2,2) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-food-waste-q3','A','It required students to skip lunch.',0) ON CONFLICT (question_id,option_id) DO NOTHING;
INSERT INTO public.listening_options (question_id,option_id,option_text,sort_order) VALUES ('original-g9-20260922-food-waste-q3','B','It used more colourful posters.',1) ON CONFLICT (question_id,option_id) DO NOTHING;
